{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.sales_for_auto as WITH mp_sor as ( SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(style_, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(style_, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(style_, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(style_, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(style_, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, style_ sku_group, \'Marketplace\' AS channel, \'SOR\' AS mode, SUM(TRY_TO_NUMBER(REPLACE(sales, \',\', \'\'))) AS qty, SUM(TRY_TO_NUMBER(REPLACE(revenue, \',\', \'\'))) AS gross_sales_value FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date>=20260301 GROUP BY 1,2,3,4 UNION ALL SELECT TO_DATE(order_date_key, \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(style_, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(style_, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(style_, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(style_, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(style_, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, style_ sku_group, \'Marketplace\' AS channel, \'SOR\' AS mode, SUM(TRY_TO_NUMBER(REPLACE(units, \',\', \'\'))) AS qty, SUM( TRY_TO_NUMBER(REPLACE(sp_per_unit_, \',\', \'\')) * TRY_TO_NUMBER(REPLACE(units, \',\', \'\')) ) AS gross_sales_value FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1,2,3,4 ), sor as ( select date,sku_group_clean,sku_group,channel,mode, qty, gross_sales_value from mp_sor ), base_sales_1 AS ( SELECT date, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' WHEN type = \'Store\' THEN \'Offline\' END AS channel, \'B2C\' Mode, SUM(gross_sales::INT) AS gross_sales_value, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2,3,4 ), base_Sales as ( select date,sku_group_clean,sku_group,channel ,sum(qty) qty,sum(gross_sales_value) gross_sales_value from ( select date,sku_group_clean,sku_group,channel,mode,qty,gross_sales_value from base_sales_1 union all select date,sku_group_clean,sku_group,channel,mode,qty,gross_sales_value from sor ) group by 1,2,3,4 ), mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, avg(MRP) MRP FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' Group by 1 ), meta_map AS ( SELECT UPPER(TRIM(REPLACE(a.SKU_GROUP, \' \', \'\'))) AS sku_group, UPPER( IFF( UPPER(REPLACE(a.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(a.cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1, 2 ), temp as ( with a as ( select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ) select UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean from a ), as_of AS ( SELECT CURRENT_DATE() AS as_of_date ), inv_current_by_sku AS ( SELECT UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, sum(COALESCE(qty_available, 0)+COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS inv_current, sum(COALESCE(qty_available, 0)) AS online_inv_current, sum(COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS offline_inv_current, sum(qty_bad_inventory) bad_inv, sum(qty_blocked) blocked_inv FROM snitch_db.maplemonk.cogs_daily_snapshot s WHERE s.date = CURRENT_DATE() -1 GROUP BY 1 ), inward_lots AS ( SELECT UPPER( IFF( UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(p.final_type) = \'new inward\' GROUP BY 1,2 ), inward_lots_fifo AS ( SELECT il.*, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM inward_lots il ), inward_total AS ( SELECT sku_group_clean, SUM(inward_qty) AS total_inward_qty FROM inward_lots GROUP BY 1 ), fifo_remaining_by_lot AS ( SELECT f.sku_group_clean, f.inward_date, f.inward_qty, ic.inv_current, ic.online_inv_current, ic.offline_inv_current, ic.bad_inv, ic.blocked_inv, it.total_inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty, DATEDIFF(\'day\', f.inward_date, CURRENT_DATE()) AS lot_age_days FROM inward_lots_fifo f LEFT JOIN inv_current_by_sku ic ON f.sku_group_clean = ic.sku_group_clean LEFT JOIN inward_total it ON f.sku_group_clean = it.sku_group_clean ), inv_ageing_fifo AS ( SELECT sku_group_clean, MAX(inv_current) AS inv_current, max(online_inv_current) online_inv_current, max(offline_inv_current) offline_inv_current, max(bad_inv) bad_inv, max(blocked_inv) blocked_inv, SUM(remaining_qty) AS remaining_qty_total, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM(remaining_qty * lot_age_days) / NULLIF(SUM(remaining_qty),0) END AS weighted_age_days FROM fifo_remaining_by_lot GROUP BY 1 ), inv_ageing as ( SELECT sku_group_clean , inv_current, remaining_qty_total, weighted_age_days, online_inv_current,offline_inv_current,bad_inv,blocked_inv, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS inventory_ageing_bucket FROM inv_ageing_fifo ) SELECT DATE_TRUNC(\'month\', bs.date) month, bs.channel, COALESCE(m_exact.l1_category, m_parent.l1_category) AS l1_category, COALESCE(m_exact.category, m_parent.category) AS category, COALESCE(m_exact.meta1, m_parent.meta1) AS meta1, COALESCE(m_exact.meta2, m_parent.meta2) AS meta2, COALESCE(m_exact.meta3, m_parent.meta3) AS meta3, max(COALESCE(m_exact.cogs, m_parent.cogs)) cogs, avg(mrp.MRP) mrp, SUM(bs.gross_sales_value) AS gross_sales_value, SUM(bs.qty * mrp.MRP) AS mrp_value, SUM(bs.qty) AS qty, SUM(bs.qty * COALESCE(m_exact.cogs, m_parent.cogs)) AS cogs_sold FROM base_sales bs full outer join inv_ageing ia ON ia.sku_group_clean = bs.sku_group_clean LEFT JOIN mrp_map mrp ON mrp.sku_group_clean = bs.sku_group_clean LEFT JOIN meta_map m_exact ON UPPER(TRIM(REPLACE(bs.sku_group, \' \', \'\'))) = m_exact.sku_group LEFT JOIN meta_map m_parent ON m_parent.sku_group = m_parent.sku_group_clean AND m_parent.sku_group_clean = bs.sku_group_clean left join (select sku_group,color from snitch_db.maplemonk.metafields_data ) cm ON cm.sku_group = bs.sku_group where bs.date >= \'2026-08-01\' group by 1,2,3,4,5,6,7 ; create or replace table snitch_db.maplemonk.inv_for_auto as WITH wh_inv AS ( SELECT Date AS inv_date, UPPER(TRIM( LEFT(\"Item SkuCode\", LENGTH(\"Item SkuCode\") - POSITION(\'-\' IN REVERSE(\"Item SkuCode\"))) )) AS sku_group, SUM(inventory) AS wh_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL-NORTH-TAURU\') AND Date >= \'2026-07-01\' AND Date <= CURRENT_DATE() GROUP BY 1, 2 ), wh_inv_split AS ( SELECT inv_date, sku_group, CASE WHEN UPPER(sku_group) LIKE \'MP%\' THEN coalesce(wh_qty,0) ELSE 0 END AS mp_inv, CASE WHEN UPPER(sku_group) LIKE \'MP%\' THEN 0 ELSE coalesce(wh_qty,0) END AS online_inv FROM wh_inv ), offline_inv AS ( SELECT date AS inv_date, UPPER(TRIM(sku_group)) AS sku_group, SUM( COALESCE(XS_UNITS,0)+COALESCE(S_UNITS,0)+COALESCE(M_UNITS,0)+COALESCE(L_UNITS,0) + COALESCE(XL_UNITS,0)+COALESCE(XXL_UNITS,0)+COALESCE(XL3_UNITS,0)+COALESCE(XL4_UNITS,0) + COALESCE(XL5_UNITS,0)+COALESCE(XL6_UNITS,0) + COALESCE(JIT_XS_UNITS,0)+COALESCE(JIT_S_UNITS,0)+COALESCE(JIT_M_UNITS,0)+COALESCE(JIT_L_UNITS,0) + COALESCE(JIT_XL_UNITS,0)+COALESCE(JIT_2XL_UNITS,0)+COALESCE(JIT_3XL_UNITS,0) + COALESCE(JIT_4XL_UNITS,0) + COALESCE(JIT_5XL_UNITS,0)+COALESCE(JIT_6XL_UNITS,0) ) AS offline_qty FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2026-07-01\' AND date <= CURRENT_DATE() GROUP BY 1, 2 ), combined_inv AS ( SELECT COALESCE(w.inv_date, o.inv_date) AS inv_date, COALESCE(w.sku_group, o.sku_group) AS sku_group, COALESCE(w.mp_inv, 0) AS mp_inv, COALESCE(w.online_inv, 0) AS online_inv, COALESCE(o.offline_qty,0) AS offline_inv FROM wh_inv_split w FULL OUTER JOIN offline_inv o ON w.sku_group = o.sku_group AND w.inv_date = o.inv_date ), meta_map AS ( SELECT UPPER(TRIM(REPLACE(a.SKU_GROUP, \' \', \'\'))) AS sku_group, UPPER( IFF( UPPER(REPLACE(a.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(a.cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1, 2 ), ff as ( SELECT c.inv_date, COALESCE(m_exact.l1_category, m_parent.l1_category) AS l1_category, COALESCE(m_exact.category, m_parent.category) AS category, COALESCE(m_exact.meta1, m_parent.meta1) AS meta1, COALESCE(m_exact.meta2, m_parent.meta2) AS meta2, COALESCE(m_exact.meta3, m_parent.meta3) AS meta3, SUM(c.mp_inv) AS mp_inv_qty, SUM(c.online_inv) AS online_inv_qty, SUM(c.offline_inv) AS offline_inv_qty, SUM(c.mp_inv + c.online_inv + c.offline_inv) AS total_inv_qty, COALESCE(m_exact.cogs, m_parent.cogs) AS cogs, SUM(c.mp_inv) * COALESCE(m_exact.cogs, m_parent.cogs) AS mp_inv_value, SUM(c.online_inv) * COALESCE(m_exact.cogs, m_parent.cogs) AS online_inv_value, SUM(c.offline_inv) * COALESCE(m_exact.cogs, m_parent.cogs) AS offline_inv_value, SUM(c.mp_inv + c.online_inv + c.offline_inv) * COALESCE(m_exact.cogs, m_parent.cogs) AS total_inv_value FROM combined_inv c LEFT JOIN meta_map m_exact ON UPPER(TRIM(REPLACE(c.sku_group, \' \', \'\'))) = m_exact.sku_group LEFT JOIN meta_map m_parent ON m_parent.sku_group = m_parent.sku_group_clean AND m_parent.sku_group_clean = UPPER( IFF( UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 1) ) ) GROUP BY c.inv_date,2, 3,4,5,6,COALESCE(m_exact.cogs, m_parent.cogs) ORDER BY c.inv_date) select inv_date, l1_category, category, meta1, meta2, meta3, SUM(mp_inv_qty) AS mp_inv_qty, SUM(online_inv_qty) AS online_inv_qty, SUM(offline_inv_qty) AS offline_inv_qty, SUM(total_inv_qty) AS total_inv_qty, SUM(mp_inv_value) AS mp_inv_value, SUM(online_inv_value) AS online_inv_value, SUM(offline_inv_value) AS offline_inv_value, SUM(total_inv_value) AS total_inv_value from ff group by 1,2,3,4,5,6; create or replace table snitch_db.maplemonk.returns_data as WITH sales_b2c AS ( SELECT date, sku_group, CASE WHEN type = \'Shopify\' THEN \'SHOPIFY\' WHEN type = \'Marketplace\' THEN \'MP\' WHEN type = \'Store\' THEN \'OFFLINE\' END AS channel, SUM(gross_sales::FLOAT) AS revenue, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1, 2, 3 ), sales_sor AS ( SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, style_ AS sku_group, \'MP\' AS channel, SUM(TRY_TO_NUMBER(REPLACE(revenue, \',\', \'\'))) AS revenue, SUM(TRY_TO_NUMBER(REPLACE(sales, \',\', \'\'))) AS qty FROM snitch_db.maplemonk.mp_sor_sales_myntra WHERE order_created_date >= 20210101 GROUP BY 1, 2, 3 UNION ALL SELECT TO_DATE(order_date_key, \'YYYYMMDD\'), style_, \'MP\', SUM(TRY_TO_NUMBER(REPLACE(sp_per_unit_, \',\', \'\')) * TRY_TO_NUMBER(REPLACE(units, \',\', \'\'))), SUM(TRY_TO_NUMBER(REPLACE(units, \',\', \'\'))) FROM snitch_db.maplemonk.mp_sor_sales_flipkart GROUP BY 1, 2, 3 ), sales_fact AS ( SELECT date, sku_group, SUM(revenue) AS overall_revenue, SUM(qty) AS overall_qty, SUM(CASE WHEN channel = \'SHOPIFY\' THEN revenue ELSE 0 END) AS shopify_revenue, SUM(CASE WHEN channel = \'SHOPIFY\' THEN qty ELSE 0 END) AS shopify_qty, SUM(CASE WHEN channel = \'MP\' THEN revenue ELSE 0 END) AS mp_revenue, SUM(CASE WHEN channel = \'MP\' THEN qty ELSE 0 END) AS mp_qty, SUM(CASE WHEN channel = \'OFFLINE\' THEN revenue ELSE 0 END) AS offline_revenue, SUM(CASE WHEN channel = \'OFFLINE\' THEN qty ELSE 0 END) AS offline_qty FROM ( SELECT date, sku_group, channel, revenue, qty FROM sales_b2c UNION ALL SELECT date, sku_group, channel, revenue, qty FROM sales_sor ) GROUP BY 1, 2 ), overall_returns_fact AS ( SELECT \"PUTAWAY_UPDATED\"::DATE AS date, UPPER(TRIM(REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") )))) AS sku_group, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS overall_returns_qty FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'b2c return%\' GROUP BY 1, 2 ), shopify_returns_fact AS ( SELECT order_date::DATE AS date, sku_group, SUM(return_qty) AS shopify_returns_qty FROM snitch_db.maplemonk.return_fact_items WHERE reason NOT IN (\'not_returned\') GROUP BY 1, 2 ), base_spine AS ( SELECT date, sku_group FROM sales_fact UNION SELECT date, sku_group FROM overall_returns_fact UNION SELECT date, sku_group FROM shopify_returns_fact ), meta_map AS ( SELECT UPPER(IFF( UPPER(REPLACE(SKU_GROUP,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',1)||\'-\'||SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',2), SPLIT_PART(REPLACE(SKU_GROUP,\' \',\'\'),\'-\',1) )) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, max(cogs) as cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ) SELECT bs.date, bs.sku_group, COALESCE(sf.overall_revenue, 0) AS overall_revenue, COALESCE(sf.overall_qty, 0) AS overall_qty, COALESCE(sf.shopify_revenue, 0) AS shopify_revenue, COALESCE(sf.shopify_qty, 0) AS shopify_qty, COALESCE(sf.mp_revenue, 0) AS mp_revenue, COALESCE(sf.mp_qty, 0) AS mp_qty, COALESCE(sf.offline_revenue, 0) AS offline_revenue, COALESCE(sf.offline_qty, 0) AS offline_qty, COALESCE(orf.overall_returns_qty, 0) AS overall_returns_qty, COALESCE(srf.shopify_returns_qty, 0) AS shopify_returns_qty FROM base_spine bs LEFT JOIN sales_fact sf ON bs.sku_group = sf.sku_group AND bs.date = sf.date LEFT JOIN overall_returns_fact orf ON bs.sku_group = orf.sku_group AND bs.date = orf.date LEFT JOIN shopify_returns_fact srf ON bs.sku_group = srf.sku_group AND bs.date = srf.date left join meta_map mm on UPPER(IFF( UPPER(REPLACE(bs.SKU_GROUP,\' \',\'\')) LIKE \'MP%\' OR UPPER(REPLACE(bs.SKU_GROUP,\' \',\'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(bs.SKU_GROUP,\' \',\'\'),\'-\',1)||\'-\'||SPLIT_PART(REPLACE(bs.SKU_GROUP,\' \',\'\'),\'-\',2), SPLIT_PART(REPLACE(bs.SKU_GROUP,\' \',\'\'),\'-\',1) )) =sku_group_clean ORDER BY bs.date DESC, bs.sku_group ; create or replace table snitch_db.maplemonk.sales_for_auto_2 as WITH mp_sor as ( SELECT TRY_TO_DATE(NULLIF(TRIM(order_created_date), \'\'), \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(a.style, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.style, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.style, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.style, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.style, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, upper(trim(a.style)) sku_group, \'MP-SOR\' AS channel, \'SOR\' AS mode, SUM(replace(a.sales, \',\', \'\'))::NUMBER AS qty, SUM(replace(a.revenue, \',\', \'\'))::NUMBER AS gross_sales_value FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a GROUP BY 1,2,3,4,5 UNION ALL SELECT TRY_TO_DATE(NULLIF(TRIM(order_date_key), \'\'), \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(a.STYLE, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.STYLE, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.STYLE, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.STYLE, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.STYLE, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, upper(trim(a.STYLE)) sku_group, \'MP-SOR\' AS channel, \'SOR\' AS mode, SUM(replace(a.units, \',\', \'\'))::NUMBER AS qty, SUM(replace(a.SP_Qty, \',\', \'\'))::NUMBER AS gross_sales_value FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a GROUP BY 1,2,3,4,5 ), sor as ( select date,sku_group_clean,sku_group,channel,mode, qty, gross_sales_value from mp_sor ), base_sales_1 AS ( SELECT date, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' WHEN type = \'Store\' THEN \'Offline\' END AS channel, \'B2C\' Mode, SUM(gross_sales::INT) AS gross_sales_value, SUM(gross_quantity::INT) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1,2,3,4 ), base_Sales as ( select date,sku_group_clean,sku_group,channel ,sum(qty) qty,sum(gross_sales_value) gross_sales_value from ( select date,sku_group_clean,sku_group,channel,mode,qty,gross_sales_value from base_sales_1 union all select date,sku_group_clean,sku_group,channel,mode,qty,gross_sales_value from sor ) group by 1,2,3,4 ), mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(sku, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(sku, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, avg(MRP) MRP FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' Group by 1 ), meta_map AS ( SELECT UPPER(TRIM(REPLACE(a.SKU_GROUP, \' \', \'\'))) AS sku_group, UPPER( IFF( UPPER(REPLACE(a.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(a.cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1, 2 ), meta_map_parent AS ( SELECT sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta1 END), MIN(meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta2 END), MIN(meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta3 END), MIN(meta3) ) AS meta3, MAX(cogs) AS cogs FROM meta_map GROUP BY sku_group_clean ), temp as ( with a as ( select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ) select UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean from a ), as_of AS ( SELECT CURRENT_DATE() AS as_of_date ), inv_current_by_sku AS ( SELECT UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, sum(COALESCE(qty_available, 0)+COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS inv_current, sum(COALESCE(qty_available, 0)) AS online_inv_current, sum(COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS offline_inv_current, sum(qty_bad_inventory) bad_inv, sum(qty_blocked) blocked_inv FROM snitch_db.maplemonk.cogs_daily_snapshot s WHERE s.date = CURRENT_DATE() -1 GROUP BY 1 ), inward_lots AS ( SELECT UPPER( IFF( UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(p.final_type) = \'new inward\' GROUP BY 1,2 ), inward_lots_fifo AS ( SELECT il.*, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM inward_lots il ), inward_total AS ( SELECT sku_group_clean, SUM(inward_qty) AS total_inward_qty FROM inward_lots GROUP BY 1 ), fifo_remaining_by_lot AS ( SELECT f.sku_group_clean, f.inward_date, f.inward_qty, ic.inv_current, ic.online_inv_current, ic.offline_inv_current, ic.bad_inv, ic.blocked_inv, it.total_inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty, DATEDIFF(\'day\', f.inward_date, CURRENT_DATE()) AS lot_age_days FROM inward_lots_fifo f LEFT JOIN inv_current_by_sku ic ON f.sku_group_clean = ic.sku_group_clean LEFT JOIN inward_total it ON f.sku_group_clean = it.sku_group_clean ), inv_ageing_fifo AS ( SELECT sku_group_clean, MAX(inv_current) AS inv_current, max(online_inv_current) online_inv_current, max(offline_inv_current) offline_inv_current, max(bad_inv) bad_inv, max(blocked_inv) blocked_inv, SUM(remaining_qty) AS remaining_qty_total, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM(remaining_qty * lot_age_days) / NULLIF(SUM(remaining_qty),0) END AS weighted_age_days FROM fifo_remaining_by_lot GROUP BY 1 ), inv_ageing as ( SELECT sku_group_clean , inv_current, remaining_qty_total, weighted_age_days, online_inv_current,offline_inv_current,bad_inv,blocked_inv, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS inventory_ageing_bucket FROM inv_ageing_fifo ) SELECT bs.date AS date, bs.channel, COALESCE(m_exact.l1_category, m_parent.l1_category) AS l1_category, COALESCE(m_exact.category, m_parent.category) AS category, COALESCE(m_exact.meta1, m_parent.meta1) AS meta1, COALESCE(m_exact.meta2, m_parent.meta2) AS meta2, COALESCE(m_exact.meta3, m_parent.meta3) AS meta3, max(COALESCE(m_exact.cogs, m_parent.cogs)) cogs, avg(mrp.MRP) mrp, SUM(bs.gross_sales_value) AS gross_sales_value, SUM(bs.qty * mrp.MRP) AS mrp_value, SUM(bs.qty) AS qty, SUM(bs.qty * COALESCE(m_exact.cogs, m_parent.cogs)) AS cogs_sold FROM base_sales bs full outer join inv_ageing ia ON ia.sku_group_clean = bs.sku_group_clean LEFT JOIN mrp_map mrp ON mrp.sku_group_clean = bs.sku_group_clean LEFT JOIN meta_map m_exact ON UPPER(TRIM(REPLACE(bs.sku_group, \' \', \'\'))) = m_exact.sku_group LEFT JOIN meta_map_parent m_parent ON m_parent.sku_group_clean = bs.sku_group_clean left join (select sku_group,color from snitch_db.maplemonk.metafields_data ) cm ON cm.sku_group = bs.sku_group where bs.date >= \'2025-01-01\' group by 1,2,3,4,5,6,7 ; create or replace table snitch_db.maplemonk.sales_for_auto_3 as WITH mp_sor as ( SELECT TRY_TO_DATE(NULLIF(TRIM(order_created_date), \'\'), \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(a.style, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.style, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.style, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.style, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.style, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, upper(trim(a.style)) sku_group, \'MP-SOR\' AS channel, \'SOR\' AS mode, SUM(replace(a.sales, \',\', \'\'))::NUMBER AS qty, SUM(replace(a.revenue, \',\', \'\'))::NUMBER AS gross_sales_value FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a GROUP BY 1,2,3,4,5 UNION ALL SELECT TRY_TO_DATE(NULLIF(TRIM(order_date_key), \'\'), \'YYYYMMDD\') AS date, UPPER( IFF( UPPER(REPLACE(a.STYLE, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(a.STYLE, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(a.STYLE, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(a.STYLE, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(a.STYLE, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, upper(trim(a.STYLE)) sku_group, \'MP-SOR\' AS channel, \'SOR\' AS mode, SUM(replace(a.units, \',\', \'\'))::NUMBER AS qty, SUM(replace(a.SP_Qty, \',\', \'\'))::NUMBER AS gross_sales_value FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a GROUP BY 1,2,3,4,5 ), sor as ( select date,sku_group_clean,sku_group,channel,mode, qty, gross_sales_value from mp_sor ), base_sales_1 AS ( SELECT date, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(SKU_GROU