PER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3) ) AS meta3, MAX(a.cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1, 2 ), meta_map_parent AS ( SELECT sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta1 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta1 END), MIN(meta1) ) AS meta1, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta2 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta2 END), MIN(meta2) ) AS meta2, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN meta3 END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN meta3 END), MIN(meta3) ) AS meta3, MAX(cogs) AS cogs FROM meta_map GROUP BY sku_group_clean ), temp as ( with a as ( select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ) select UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean from a ), as_of AS ( SELECT CURRENT_DATE() AS as_of_date ), inv_current_by_sku AS ( SELECT UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, sum(COALESCE(qty_available, 0)+COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS inv_current, sum(COALESCE(qty_available, 0)) AS online_inv_current, sum(COALESCE(qty_offline_available, 0)+COALESCE(qty_jit, 0)) AS offline_inv_current, sum(qty_bad_inventory) bad_inv, sum(qty_blocked) blocked_inv FROM snitch_db.maplemonk.cogs_daily_snapshot s WHERE s.date = CURRENT_DATE() -1 GROUP BY 1 ), inward_lots AS ( SELECT UPPER( IFF( UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', CONCAT( SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1), \'-\', SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 2) ), SPLIT_PART(REPLACE(p.\"Item Type skuCode\", \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, p.\"PUTAWAY_UPDATED\"::DATE AS inward_date, SUM(p.\"PUTAWAY_COMPLETED_QUANTITY\") AS inward_qty FROM snitch_db.maplemonk.putaway_tracking p WHERE LOWER(p.final_type) = \'new inward\' GROUP BY 1,2 ), inward_lots_fifo AS ( SELECT il.*, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_inward_qty, SUM(inward_qty) OVER ( PARTITION BY sku_group_clean ORDER BY inward_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - inward_qty AS cum_inward_qty_prev FROM inward_lots il ), inward_total AS ( SELECT sku_group_clean, SUM(inward_qty) AS total_inward_qty FROM inward_lots GROUP BY 1 ), fifo_remaining_by_lot AS ( SELECT f.sku_group_clean, f.inward_date, f.inward_qty, ic.inv_current, ic.online_inv_current, ic.offline_inv_current, ic.bad_inv, ic.blocked_inv, it.total_inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) AS consumed_qty, GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ) AS consumed_in_lot, GREATEST( f.inward_qty - GREATEST( LEAST( f.inward_qty, GREATEST( COALESCE(it.total_inward_qty,0) - COALESCE(ic.inv_current,0), 0 ) - f.cum_inward_qty_prev ), 0 ), 0 ) AS remaining_qty, DATEDIFF(\'day\', f.inward_date, CURRENT_DATE()) AS lot_age_days FROM inward_lots_fifo f LEFT JOIN inv_current_by_sku ic ON f.sku_group_clean = ic.sku_group_clean LEFT JOIN inward_total it ON f.sku_group_clean = it.sku_group_clean ), inv_ageing_fifo AS ( SELECT sku_group_clean, MAX(inv_current) AS inv_current, max(online_inv_current) online_inv_current, max(offline_inv_current) offline_inv_current, max(bad_inv) bad_inv, max(blocked_inv) blocked_inv, SUM(remaining_qty) AS remaining_qty_total, CASE WHEN SUM(remaining_qty) = 0 THEN 0 ELSE SUM(remaining_qty * lot_age_days) / NULLIF(SUM(remaining_qty),0) END AS weighted_age_days FROM fifo_remaining_by_lot GROUP BY 1 ), inv_ageing as ( SELECT sku_group_clean , inv_current, remaining_qty_total, weighted_age_days, online_inv_current,offline_inv_current,bad_inv,blocked_inv, CASE WHEN weighted_age_days <= 30 THEN \'0-30\' WHEN weighted_age_days <= 60 THEN \'30-60\' WHEN weighted_age_days <= 90 THEN \'60-90\' WHEN weighted_age_days <= 120 THEN \'90-120\' WHEN weighted_age_days <= 180 THEN \'120-180\' WHEN weighted_age_days <= 270 THEN \'180-270\' WHEN weighted_age_days <= 360 THEN \'270-360\' ELSE \'360+\' END AS inventory_ageing_bucket FROM inv_ageing_fifo ) SELECT bs.date AS date, bs.channel, bs.sku_group, COALESCE(m_exact.l1_category, m_parent.l1_category) AS l1_category, COALESCE(m_exact.category, m_parent.category) AS category, COALESCE(m_exact.meta1, m_parent.meta1) AS meta1, COALESCE(m_exact.meta2, m_parent.meta2) AS meta2, COALESCE(m_exact.meta3, m_parent.meta3) AS meta3, max(COALESCE(m_exact.cogs, m_parent.cogs)) cogs, avg(mrp.MRP) mrp, SUM(bs.gross_sales_value) AS gross_sales_value, SUM(bs.qty * mrp.MRP) AS mrp_value, SUM(bs.qty) AS qty, SUM(bs.qty * COALESCE(m_exact.cogs, m_parent.cogs)) AS cogs_sold FROM base_sales bs full outer join inv_ageing ia ON ia.sku_group_clean = bs.sku_group_clean LEFT JOIN mrp_map mrp ON mrp.sku_group_clean = bs.sku_group_clean LEFT JOIN meta_map m_exact ON UPPER(TRIM(REPLACE(bs.sku_group, \' \', \'\'))) = m_exact.sku_group LEFT JOIN meta_map_parent m_parent ON m_parent.sku_group_clean = bs.sku_group_clean left join (select sku_group,color from snitch_db.maplemonk.metafields_data ) cm ON cm.sku_group = bs.sku_group where bs.date >= \'2025-01-01\' group by 1,2,3,4,5,6,7,8 ; create or replace table snitch_db.maplemonk.inv_for_auto_detail as WITH store_daily AS ( SELECT DATE, SKU_GROUP AS sku_group, MARKETPLACE_MAPPED AS channel_name, COALESCE(XS_UNITS, 0) + COALESCE(JIT_XS_UNITS, 0) AS xs, COALESCE(S_UNITS, 0) + COALESCE(JIT_S_UNITS, 0) AS s, COALESCE(M_UNITS, 0) + COALESCE(JIT_M_UNITS, 0) AS m, COALESCE(L_UNITS, 0) + COALESCE(JIT_L_UNITS, 0) AS l, COALESCE(XL_UNITS, 0) + COALESCE(JIT_XL_UNITS, 0) AS xl, COALESCE(XXL_UNITS, 0) + COALESCE(JIT_2XL_UNITS, 0) AS xl2, COALESCE(XL3_UNITS, 0) + COALESCE(JIT_3XL_UNITS, 0) AS xl3, COALESCE(XL4_UNITS, 0) + COALESCE(JIT_4XL_UNITS, 0) AS xl4, COALESCE(XL5_UNITS, 0) + COALESCE(JIT_5XL_UNITS, 0) AS xl5, COALESCE(XL6_UNITS, 0) + COALESCE(JIT_6XL_UNITS, 0) AS xl6, COALESCE(inventory, 0) + COALESCE(JIT_QTY, 0) AS inv, FROM snitch_db.maplemonk.offline_master_daily_report_1 ), store_month_end_date AS ( SELECT sku_group, channel_name, DATE_TRUNC(\'month\', DATE) AS month_start, MAX(DATE) AS max_date FROM store_daily GROUP BY 1, 2, 3 ), store_month_end AS ( SELECT upper(sd.sku_group) SKU_group, \'Store\' AS channel_type, sd.channel_name, TO_VARCHAR(sme.month_start, \'MON-YYYY\') AS month, sd.xs, sd.s, sd.m, sd.l, sd.xl, sd.xl2, sd.xl3, sd.xl4, sd.xl5, sd.xl6, case when xs+s+m+l+xl+xl2+xl3+xl4+xl5+xl6 > 0 then xs+s+m+l+xl+xl2+xl3+xl4+xl5+xl6 else inv end total FROM store_daily sd JOIN store_month_end_date sme ON sd.sku_group = sme.sku_group AND sd.channel_name = sme.channel_name AND sd.DATE = sme.max_date where sd.channel_name not like \'%WH%\' ), wh_daily AS ( SELECT DATE AS date, SPLIT_PART(REPLACE(\"Item SkuCode\", \' \', \'\'), \'-\', 1) AS sku_group_raw, \"Item SkuCode\" AS full_sku, REGEXP_REPLACE(\"Item SkuCode\", \'-[^-]+$\', \'\') AS sku_group, REGEXP_REPLACE(\"Item SkuCode\", \'^.*-\', \'\') AS raw_size, inventory AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') ), wh_normalized AS ( SELECT date, sku_group, qty, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN raw_size WHEN raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'39\' THEN \'2XL\' WHEN raw_size = \'41\' THEN \'4XL\' WHEN raw_size = \'43\' THEN \'5XL\' WHEN raw_size = \'45\' THEN \'6XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size FROM wh_daily ), wh_pivot_daily AS ( SELECT date, upper(sku_group) sku_group, SUM( CASE WHEN size = \'XS\' THEN qty ELSE 0 END ) AS xs, SUM( CASE WHEN size = \'S\' THEN qty ELSE 0 END ) AS s, SUM( CASE WHEN size = \'M\' THEN qty ELSE 0 END ) AS m, SUM( CASE WHEN size = \'L\' THEN qty ELSE 0 END ) AS l, SUM( CASE WHEN size = \'XL\' THEN qty ELSE 0 END ) AS xl, SUM( CASE WHEN size = \'2XL\' THEN qty ELSE 0 END ) AS xl2, SUM( CASE WHEN size = \'3XL\' THEN qty ELSE 0 END ) AS xl3, SUM( CASE WHEN size = \'4XL\' THEN qty ELSE 0 END ) AS xl4, SUM( CASE WHEN size = \'5XL\' THEN qty ELSE 0 END ) AS xl5, SUM( CASE WHEN size = \'6XL\' THEN qty ELSE 0 END ) AS xl6, sum(qty) total FROM wh_normalized GROUP BY 1, 2 ), wh_month_end_date AS ( SELECT sku_group, DATE_TRUNC(\'month\', date) AS month_start, MAX(date) AS max_date FROM wh_pivot_daily GROUP BY 1, 2 ), wh_month_end AS ( SELECT wp.sku_group, \'Warehouse\' AS channel_type, \'Warehouse\' AS channel_name, TO_VARCHAR(wme.month_start, \'MON-YYYY\') AS month, wp.xs, wp.s, wp.m, wp.l, wp.xl, wp.xl2, wp.xl3, wp.xl4, wp.xl5, wp.xl6, total FROM wh_pivot_daily wp JOIN wh_month_end_date wme ON wp.sku_group = wme.sku_group AND wp.date = wme.max_date ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END ), MIN( CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END ), MIN( CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END ), MIN( CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END ), MIN(l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END ), MIN( CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END ), MIN( CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END ), MIN( CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END ), MIN(category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(meta1)) = \'SHIRTS\' THEN meta1 END ), MIN( CASE WHEN UPPER(TRIM(meta1)) = \'TSHIRTS\' THEN meta1 END ), MIN( CASE WHEN UPPER(TRIM(meta1)) = \'JEANS\' THEN meta1 END ), MIN( CASE WHEN UPPER(TRIM(meta1)) = \'TROUSERS\' THEN meta1 END ), MIN(meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(meta2)) = \'SHIRTS\' THEN meta2 END ), MIN( CASE WHEN UPPER(TRIM(meta2)) = \'TSHIRTS\' THEN meta2 END ), MIN( CASE WHEN UPPER(TRIM(meta2)) = \'JEANS\' THEN meta2 END ), MIN( CASE WHEN UPPER(TRIM(meta2)) = \'TROUSERS\' THEN meta2 END ), MIN(meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(meta3)) = \'SHIRTS\' THEN meta3 END ), MIN( CASE WHEN UPPER(TRIM(meta3)) = \'TSHIRTS\' THEN meta3 END ), MIN( CASE WHEN UPPER(TRIM(meta3)) = \'JEANS\' THEN meta3 END ), MIN( CASE WHEN UPPER(TRIM(meta3)) = \'TROUSERS\' THEN meta3 END ), MIN(meta3) ) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), mrp_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, MAX(MRP) AS mrp FROM snitch_db.maplemonk.logic_final_item_master WHERE BRAND = \'SNITCH\' GROUP BY 1 ) select a.*, mm.* exclude(sku_group_clean), mp.mrp from ( SELECT * FROM store_month_end UNION ALL SELECT * FROM wh_month_end ) a left join meta_map mm on mm.sku_group_clean = UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) left join mrp_map mp on mm.sku_group_clean = mp.sku_group_clean where l1_category is not null;",
